    private void btnProcessActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnProcessActionPerformed
try {
    String customer = txtCustomer.getText().trim();
    String product = cmbProduct.getSelectedItem().toString();
    double price = Double.parseDouble(txtPrice.getText());

    if (customer.isEmpty() || price < 0) {
        JOptionPane.showMessageDialog(this, "Enter valid details.");
        return;
    }

    ProductCalculations calc = new ProductCalculations(price);

    String result = "Customer Name: " + customer
            + "\nProduct: " + product
            + "\nVAT: R " + calc.GetVat()
            + "\nCOMMISSION: R " + calc.GetCommission()
            + "\nTOTAL: R " + calc.GetTotal();

    JOptionPane.showMessageDialog(this, result);

    try (java.io.FileWriter writer =
            new java.io.FileWriter("data.txt", true)) {

        writer.write("DATA LOG\n");
        writer.write("**********\n");
        writer.write(result + "\n\n");
    }

} catch (NumberFormatException e) {
    JOptionPane.showMessageDialog(this, "Enter a valid price.");
} catch (java.io.IOException e) {
    JOptionPane.showMessageDialog(this, "Error saving file.");
}        // TODO add your handling code here:
    }//GEN-LAST:event_btnProcessActionPerformed

